{"cards": [{"node_code": "N_bc0fc9d3425b1aa7", "definition": "研究盾构法与TBM法隧道施工的核心技术，涵盖设备选型、掘进机理、管片拼装、同步注浆及开挖面稳定控制，适用于软土、硬岩及复合地层。", "boundary": "本节点聚焦于机械化掘进隧道的设备与工艺。边界包括盾构/TBM类型、刀盘设计、掘进参数、管片结构及拼装、同步注浆材料与工艺、开挖面支护及地表沉降控制。不包含钻爆法施工（归入山岭隧道钻爆法），也不包含沉管法（归入沉管与水下隧道）。", "includes": ["盾构与TBM设备结构、类型选择及刀盘刀具设计", "掘进过程控制、开挖面稳定、同步注浆及管片拼装技术", "盾构/TBM施工中的地层适应性分析及地表变形控制"], "excludes": ["采用钻爆法施工的山岭隧道（归入山岭隧道钻爆法）", "采用浮运沉放法施工的水下隧道（归入沉管与水下隧道）"], "sibling_distinctions": [{"other_code": "N_01bacb7e5e0f7b3e", "rule": "本节点侧重机械化连续掘进（盾构/TBM），兄弟节点侧重人工或机械钻孔爆破循环施工。"}, {"other_code": "N_a6eb3d58373c265d", "rule": "本节点侧重在土体或岩层中掘进成型，兄弟节点侧重预制管节在水下浮运、沉放及对接。"}, {"other_code": "N_9858d0d1d1b9529f", "rule": "本节点侧重地下连续掘进，兄弟节点侧重浅埋条件下的明挖、盖挖或浅埋暗挖工法。"}], "cross_boundary_rule": "盾构/TBM施工中的监测数据若用于整体风险评估，可关联隧道监控量测与风险控制；但设备操作与掘进工艺主挂载于本节点。"}, {"node_code": "N_0cf01abb940a4729", "definition": "研究隧道施工及运营期间的监测量测技术、数据分析方法及风险控制体系，涵盖收敛、沉降、应力监测及风险预警与处置。", "boundary": "本节点聚焦于隧道全生命周期的安全监测与风险管理。边界包括监测方案设计、仪器选型、数据采集与分析、预警阈值设定、风险识别与处置措施。不包含具体的施工工法技术（如盾构掘进、钻爆循环），也不包含结构本身的力学设计计算。", "includes": ["隧道施工期与运营期监测量测方案、仪器及数据处理", "围岩收敛、拱顶沉降、地表沉降等关键指标监测与分析", "隧道施工风险识别、预警机制及应急处置措施"], "excludes": ["具体的隧道掘进、支护或衬砌施工工艺（归入相应工法节点）", "隧道结构的设计计算与理论分析（归入隧道支护与衬砌结构或地下结构工程）"], "sibling_distinctions": [{"other_code": "N_cde22b977a46b501", "rule": "本节点侧重监测数据的风险管理与决策，兄弟节点侧重基于监测反馈的施工方法调整（信息化施工）。"}, {"other_code": "N_d75e55b1457d1dd7", "rule": "本节点侧重施工过程中的实时监测与风险，兄弟节点侧重施工前的地质勘察与超前预报。"}], "cross_boundary_rule": "监测数据用于指导施工参数调整时，可关联新奥法与信息化施工；但监测体系本身及风险管理制度主挂载于本节点。"}, {"node_code": "N_a6eb3d58373c265d", "definition": "研究沉管法及水下隧道工程的技术，涵盖管节预制、浮运沉放、基础处理、接头连接及防水密封，适用于江河湖海等水域穿越。", "boundary": "本节点聚焦于水下隧道（特别是沉管隧道）的专项技术。边界包括管节结构设计、预制工艺、浮运与沉放技术、基槽处理、管节对接与接头防水、水下检测。不包含在土体中掘进的盾构/TBM隧道，也不包含钻爆法隧道。", "includes": ["沉管管节结构设计、预制工艺及质量控制", "浮运、沉放、定位及基槽处理技术", "管节接头连接、防水密封及水下隧道检测维护"], "excludes": ["在土体或岩层中通过掘进成型的隧道（归入盾构与TBM隧道或山岭隧道钻爆法）", "非水下环境的隧道工程"], "sibling_distinctions": [{"other_code": "N_bc0fc9d3425b1aa7", "rule": "本节点侧重预制管节的水下沉放与对接，兄弟节点侧重在土体中连续掘进成型。"}, {"other_code": "N_01bacb7e5e0f7b3e", "rule": "本节点侧重水下环境下的预制拼装，兄弟节点侧重山岭地层的钻爆施工。"}], "cross_boundary_rule": "沉管隧道的水下监测若涉及整体风险，可关联隧道监控量测与风险控制；但沉放工艺与接头技术主挂载于本节点。"}]}
